// #662546 — общие помощники экрана /admin/tenders («ניהול מכרזים שנקלטו», platform admin). Только чтение; «ניסיון חוזר» НИКОГДА не нажимается.
import { Page, expect } from '@playwright/test';

/** Известный тендер в состоянии «תקין» (QA-T6, компания QA-Co-B) — для деталей, не зависит от сбойных строк. */
export const OK_TENDER = { id: 'bbbbbbbb-0000-4000-8000-000000000006', title: 'QA-T6 upload', company: 'QA-Co-B' };
export const NO_PERMISSION = 'אין לך הרשאה למסך זה';
export const SYSTEM_ADMINS_ONLY = 'המסך זמין למנהלי מערכת בלבד.';

export const tendersRows = (page: Page) => page.locator('tbody tr');
export const tendersSearch = (page: Page) => page.getByPlaceholder('חיפוש מכרז או חברה…');
export const stateFilter = (page: Page) => page.locator('select').first();

/** Открыть /admin/tenders и дождаться заголовка и первой строки. */
export async function openTenders(page: Page) {
  await page.goto('/admin/tenders');
  await expect(page.getByRole('heading', { name: 'ניהול מכרזים שנקלטו', level: 1 })).toBeVisible();
  await expect(tendersRows(page).first()).toBeVisible();
}

/** Ссылка «פרטי מכרז» в строке тендера. */
export const detailsLink = (row: ReturnType<Page['locator']>) => row.getByRole('link', { name: 'פרטי מכרז', exact: true });

/** Страница деталей принятого тендера (admin-вид): заголовок и обязательные подписи. */
export async function expectDetailsPage(page: Page, id: string) {
  await expect(page).toHaveURL(new RegExp(`/admin/tenders/${id}$`));
  await expect(page.getByText('פרטי מכרז שנקלט', { exact: true })).toBeVisible();
  for (const label of ['חברה', 'מקור', 'נקלט בתאריך', 'מצב קליטה', 'מצב ניתוח']) {
    await expect(page.getByText(label, { exact: true }).first(), `подпись «${label}»`).toBeVisible();
  }
  await expect(page.getByRole('link', { name: 'חזרה למכרזים שנקלטו' })).toBeVisible();
}
